/* Palette and dimensions follow DESIGN.md. System mode works without JavaScript. */
:root {
  color-scheme: light dark;
  --primary: #202020;
  --secondary: #595959;
  --neutral: #f5f5f5;
  --surface: #ffffff;
  --hover: #e6e6e6;
  --error: #b3261e;
  --error-surface: #fff0ee;
  --space-xs: 0.25rem;
  --space-sm: 0.5rem;
  --space-control: 0.75rem;
  --space-md: 1rem;
  --space-lg: 1.5rem;
  --space-xl: 2rem;
  --corner: 4px;
  --target: 44px;
  font-family: sans-serif;
  font-size: 100%;
  line-height: 1.5;
  color: var(--primary);
  background: var(--neutral);
  accent-color: var(--primary);
}
@media (prefers-color-scheme: dark) {
  :root:not(:has(> head > meta[name="color-scheme"][content="light"])) {
    --primary: #ededed;
    --secondary: #b8b8b8;
    --neutral: #121212;
    --surface: #1e1e1e;
    --hover: #303030;
    --error: #ffb4ab;
    --error-surface: #36201e;
  }
}
:root:has(> head > meta[name="color-scheme"][content="dark"]) {
  color-scheme: dark;
  --primary: #ededed;
  --secondary: #b8b8b8;
  --neutral: #121212;
  --surface: #1e1e1e;
  --hover: #303030;
  --error: #ffb4ab;
  --error-surface: #36201e;
}
:root:has(> head > meta[name="color-scheme"][content="light"]) { color-scheme: light; }
* { box-sizing: border-box; }
body { margin: 0; }
header, main { max-inline-size: 48rem; margin-inline: auto; padding: var(--space-md); }
header { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: var(--space-md); }
h1 { font-size: 1.5rem; line-height: 1.25; margin: 0; }
h2 { font-size: 1.25rem; line-height: 1.3; margin-block: 0 var(--space-lg); }
h1, h2 { font-weight: 600; overflow-wrap: anywhere; }
.theme-control { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-sm); }
.theme-control label { font-weight: 600; }
#theme-status { flex-basis: 100%; margin: 0; color: var(--secondary); }
#theme-status:empty, #storage-error:empty, #form-error:empty { display: none; }
.save-state { margin-block-end: var(--space-xl); }
#save-status { color: var(--secondary); margin-block: 0 var(--space-sm); }
#storage-error, #form-error { color: var(--error); background: var(--error-surface); padding: var(--space-control); border-radius: var(--corner); overflow-wrap: anywhere; }
fieldset { border: 0; padding: 0; margin: 0; min-inline-size: 0; }
legend { font-weight: 600; padding: 0; margin-block-end: var(--space-sm); }
.field, .units { margin-block-end: var(--space-md); }
.field > label { display: block; font-weight: 600; margin-block-end: var(--space-xs); }
.hint { color: var(--secondary); margin-block: var(--space-xs) var(--space-sm); }
input, textarea, select, button { font: inherit; }
input:not([type="radio"]), textarea, select {
  min-block-size: var(--target); min-inline-size: var(--target); max-inline-size: 100%;
  padding: var(--space-control); border: 1px solid var(--secondary); border-radius: var(--corner);
  background: var(--surface); color: var(--primary);
}
input:not([type="radio"]), textarea { inline-size: 100%; }
textarea { resize: vertical; }
.choices { display: flex; flex-wrap: wrap; gap: var(--space-sm) var(--space-lg); }
.choices > div { display: flex; align-items: center; }
input[type="radio"] { inline-size: 1.25rem; block-size: 1.25rem; margin: 0 var(--space-sm) 0 0; }
.choices label { display: flex; align-items: center; min-block-size: var(--target); min-inline-size: var(--target); cursor: pointer; }
button {
  min-block-size: var(--target); min-inline-size: var(--target); max-inline-size: 100%;
  padding: var(--space-control); border: 1px solid var(--secondary); border-radius: var(--corner);
  background: var(--primary); color: var(--surface); font-weight: 600; cursor: pointer; overflow-wrap: anywhere;
}
button.secondary { background: var(--surface); color: var(--primary); }
button:hover, button:active { background: var(--hover); color: var(--primary); }
button:disabled { cursor: wait; }
:focus-visible { outline: 3px solid var(--primary); outline-offset: 3px; }
input[aria-invalid="true"], textarea[aria-invalid="true"] { border-color: var(--error); }
.field-error { color: var(--error); margin-block: var(--space-xs) 0; overflow-wrap: anywhere; }
.actions { display: flex; flex-wrap: wrap; gap: var(--space-control); }
#all-vehicles { margin-block-end: var(--space-lg); }
#vehicle-list { list-style: none; padding: 0; margin-block: 0 var(--space-md); }
#vehicle-list:empty { display: none; }
#vehicle-list button {
  inline-size: 100%; text-align: start; font-weight: 400; background: transparent; color: var(--primary);
  border: 0; border-block-end: 1px solid var(--secondary); border-inline-start: 4px solid transparent; border-radius: 0;
}
#vehicle-list button:hover, #vehicle-list button:active, #vehicle-list button[aria-current="true"] { background: var(--hover); }
#vehicle-list button[aria-current="true"] { border-inline-start-color: var(--primary); }
dt { font-weight: 600; }
dd { margin: 0 0 var(--space-md); overflow-wrap: anywhere; white-space: pre-wrap; font-variant-numeric: tabular-nums; }
@media (forced-colors: active) {
  :root:has(> head > meta[name="color-scheme"][content]) {
    --primary: CanvasText;
    --secondary: CanvasText;
    --neutral: Canvas;
    --surface: Canvas;
    --hover: Canvas;
    --error: CanvasText;
    --error-surface: Canvas;
  }
}

