assets.interface.js:
import { createCollection, getVehicle, saveVehicle } from './history.js';
import { summarizeVehicle } from './calculations.js';

export async function start(document, storage) {
  const byId = id => document.getElementById(id);
  const form = byId('vehicle-form');
  const view = document.defaultView;
  const theme = byId('theme');
  const scheme = document.querySelector('meta[name="color-scheme"]');
  const themeKey = 'car-maintenance-tracker.theme';
  function applyTheme(value) {
    const preference = ['light', 'dark'].includes(value) ? value : 'system';
    scheme.content = preference === 'system' ? 'light dark' : preference;
    theme.value = preference;
  }
  applyTheme(scheme.content);
  theme.addEventListener('change', () => {
    applyTheme(theme.value);
    try {
      if (theme.value === 'system') view.localStorage.removeItem(themeKey);
      else view.localStorage.setItem(themeKey, theme.value);
      byId('theme-status').textContent = '';
    } catch {
      byId('theme-status').textContent = 'Theme applies to this page only.';
    }
  });
  view.addEventListener('storage', event => {
    if (event.key === themeKey || event.key === null) {
      applyTheme(event.newValue);
      byId('theme-status').textContent = '';
    }
  });
  let snapshot;
  let editingId = null;
  let pending = false;
  let dirty = false;
  let busy = false;
  let loaded = false;

  function status(message, error = '') {
    byId('save-status').textContent = message;
    byId('storage-error').textContent = error;
    byId('retry').hidden = !error || !byId('vehicle-editor').hidden;
  }

  function screen(id, focusId) {
    for (const name of ['selection', 'vehicle-summary', 'vehicle-editor']) byId(name).hidden = name !== id;
    if (focusId) byId(focusId).focus();
  }

  function render(focus = true) {
    const list = byId('vehicle-list');
    list.replaceChildren();
    for (const vehicle of snapshot.collection.vehicles) {
      const li = document.createElement('li');
      const button = document.createElement('button');
      button.type = 'button';
      button.textContent = vehicle.name;
      if (vehicle.id === snapshot.selectedVehicleId) button.setAttribute('aria-current', 'true');
      button.addEventListener('click', async () => {
        if (busy) return;
        snapshot.selectedVehicleId = vehicle.id;
        render();
        await persist();
      });
      li.append(button);
      list.append(li);
    }
    if (snapshot.selectedVehicleId === null) {
      screen('selection', focus ? 'selection-title' : null);
      return;
    }
    const summary = summarizeVehicle(snapshot.collection, snapshot.selectedVehicleId);
    const vehicle = summary.vehicle;
    byId('vehicle-title').textContent = vehicle.name;
    byId('vehicle-description').textContent = [vehicle.year, vehicle.make, vehicle.model].filter(Boolean).join(' ');
    byId('vehicle-description').hidden = !byId('vehicle-description').textContent;
    byId('summary-units').textContent = vehicle.odometerUnit === 'km' ? 'Kilometres (km)' : 'Miles (mi)';
    byId('summary-mileage').textContent = `Unknown — ${summary.odometer.reason}`;
    byId('summary-history').textContent = `No entries yet. ${summary.history.reason}`;
    byId('summary-notes').textContent = vehicle.notes || 'No notes added.';
    screen('vehicle-summary', focus ? 'vehicle-title' : null);
  }

  async function persist() {
    busy = true;
    pending = true;
    byId('editor-fields').disabled = true;
    status('Saving on this device…');
    try {
      const result = await storage.save(snapshot);
      snapshot.revision = result.revision;
      pending = false;
      status('Saved on this device.');
      return true;
    } catch (error) {
      status('Not saved on this device.', `${error.message} Your work is still open here. Retry before closing this page.`);
      return false;
    } finally {
      busy = false;
      byId('editor-fields').disabled = false;
    }
  }

  function clearError(control) {
    control.setAttribute('aria-invalid', 'false');
    const errorId = `${control.name}-error`;
    const error = byId(errorId);
    if (error) { error.hidden = true; error.textContent = ''; }
    const descriptions = (control.getAttribute('aria-describedby') || '').split(' ').filter(value => value && value !== errorId);
    if (descriptions.length) control.setAttribute('aria-describedby', descriptions.join(' '));
    else control.removeAttribute('aria-describedby');
  }

  function showError(name, message) {
    const controls = [...form.elements].filter(control => control.name === name);
    const error = byId(`${name}-error`);
    if (!error) { byId('form-error').textContent = message; return; }
    error.textContent = message;
    error.hidden = false;
    for (const control of controls) {
      control.setAttribute('aria-invalid', 'true');
      control.setAttribute('aria-describedby', [control.getAttribute('aria-describedby'), error.id].filter(Boolean).join(' '));
    }
    controls[0].focus();
  }

  function edit(vehicleId = null) {
    if (busy) return;
    editingId = vehicleId;
    dirty = false;
    form.reset();
    byId('form-error').textContent = '';
    for (const control of form.querySelectorAll('input, textarea')) clearError(control);
    if (vehicleId !== null) {
      const vehicle = getVehicle(snapshot.collection, vehicleId);
      for (const key of ['name', 'make', 'model', 'year', 'notes']) form.elements.namedItem(key).value = vehicle[key] ?? '';
      form.elements.namedItem('odometerUnit').value = vehicle.odometerUnit;
    }
    byId('editor-title').textContent = vehicleId ? 'Edit vehicle details' : 'Add vehicle';
    byId('submit-vehicle').textContent = vehicleId ? 'Save changes' : 'Create vehicle';
    byId('retry').hidden = true;
    screen('vehicle-editor', 'vehicle-name');
  }

  form.addEventListener('input', event => {
    dirty = true;
    if (event.target.name === 'odometerUnit') {
      for (const radio of form.querySelectorAll('[name="odometerUnit"]')) clearError(radio);
    } else clearError(event.target);
    byId('form-error').textContent = '';
    byId('save-status').textContent = 'Unsaved details — submit to save on this device.';
  });

  form.addEventListener('submit', async event => {
    event.preventDefault();
    if (busy) return;
    for (const control of form.querySelectorAll('input, textarea')) {
      if (!control.validity.valid) {
        showError(control.name, control.validationMessage);
        return;
      }
    }
    const values = new view.FormData(form);
    const details = Object.fromEntries(values);
    details.odometerUnit ??= '';
    details.year = details.year === '' ? null : Number(details.year);
    try {
      const result = saveVehicle(snapshot.collection, details, editingId);
      snapshot.collection = result.collection;
      snapshot.selectedVehicleId = result.vehicleId;
      editingId = result.vehicleId;
      if (await persist()) {
        dirty = false;
        render();
      } else {
        byId('submit-vehicle').textContent = 'Retry saving details';
      }
    } catch (error) {
      showError(error.field, error.message);
    }
  });

  byId('add-vehicle').addEventListener('click', () => edit());
  byId('edit-vehicle').addEventListener('click', () => edit(snapshot.selectedVehicleId));
  byId('all-vehicles').addEventListener('click', () => {
    if (!busy) screen('selection', 'selection-title');
  });
  byId('cancel-edit').addEventListener('click', () => {
    if (busy) return;
    dirty = false;
    render();
    if (pending) byId('retry').hidden = false;
    else status(snapshot.revision ? 'Saved on this device.' : 'No vehicles saved yet.');
  });
  byId('retry').addEventListener('click', async () => {
    if (busy) return;
    if (!loaded) await load();
    else await persist();
  });
  view.addEventListener('beforeunload', event => {
    if (pending || dirty) { event.preventDefault(); event.returnValue = ''; }
  });

  async function load() {
    busy = true;
    status('Opening local vehicles…');
    try {
      snapshot = await storage.load() ?? { collection: createCollection(), selectedVehicleId: null, revision: 0 };
      loaded = true;
      render(false);
      status(snapshot.revision ? 'Saved on this device.' : 'No vehicles saved yet.');
    } catch (error) {
      status('Could not open local vehicles.', `${error.message} Existing data has not been replaced. Retry local storage to continue.`);
    } finally { busy = false; }
  }
  await load();
}

assets.history.js:
export const FORMAT = 'car-maintenance-tracker';
export const SCHEMA_VERSION = 1;

export class ValidationError extends Error {
  constructor(message, field) {
    super(message);
    this.name = 'ValidationError';
    this.field = field;
  }
}

function requireValue(condition, message, field) {
  if (!condition) throw new ValidationError(message, field);
}

function shape(value, keys, label) {
  requireValue(value !== null && typeof value === 'object' && !Array.isArray(value), `${label} must be an object.`);
  requireValue(Object.keys(value).length === keys.length && keys.every(key => Object.hasOwn(value, key)), `${label} has missing or unsupported fields.`);
}

function text(value, field, maximum, required = false) {
  requireValue(typeof value === 'string' && value.length <= maximum && (!required || value.trim().length > 0),
    `Enter ${required ? 'a non-blank' : 'an optional'} ${field} of at most ${maximum} characters.`, field);
}

function id(value) {
  requireValue(typeof value === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value), 'Expected a stable UUID.');
}

function timestamp(value) {
  requireValue(typeof value === 'string' && Number.isFinite(Date.parse(value)) && new Date(value).toISOString() === value, 'Expected an ISO edit timestamp.');
}

function vehicleDetails(vehicle) {
  text(vehicle.name, 'name', 100, true);
  requireValue(['km', 'mi'].includes(vehicle.odometerUnit), 'Choose kilometres or miles.', 'odometerUnit');
  text(vehicle.make, 'make', 100);
  text(vehicle.model, 'model', 100);
  text(vehicle.notes, 'notes', 5000);
  requireValue(vehicle.year === null || (Number.isInteger(vehicle.year) && vehicle.year >= 1 && vehicle.year <= 9999), 'Enter a year from 1 to 9999, or leave it blank.', 'year');
}

// New factual record kinds add their complete validator here, with an explicit
// schema migration and fixtures. Unknown kinds are refused, never discarded.
const recordValidators = new Map();

export function validateCollection(collection) {
  shape(collection, ['format', 'schemaVersion', 'id', 'vehicles', 'records', 'tombstones'], 'Collection');
  requireValue(collection.format === FORMAT, 'This is not a Car Maintenance Tracker collection.');
  requireValue(collection.schemaVersion === SCHEMA_VERSION, 'This collection version is not supported. Use a compatible app; your stored data has not been changed.');
  id(collection.id);
  for (const key of ['vehicles', 'records', 'tombstones']) requireValue(Array.isArray(collection[key]), `${key} must be a list.`);
  const identities = new Set([collection.id]);
  const unique = value => {
    id(value);
    requireValue(!identities.has(value), 'Duplicate record identity.');
    identities.add(value);
  };
  for (const vehicle of collection.vehicles) {
    shape(vehicle, ['id', 'name', 'odometerUnit', 'make', 'model', 'year', 'notes', 'createdAt', 'updatedAt'], 'Vehicle');
    unique(vehicle.id);
    vehicleDetails(vehicle);
    timestamp(vehicle.createdAt);
    timestamp(vehicle.updatedAt);
  }
  for (const record of collection.records) {
    requireValue(record !== null && typeof record === 'object', 'Record must be an object.');
    unique(record.id);
    requireValue(collection.vehicles.some(vehicle => vehicle.id === record.vehicleId), 'Record refers to a missing vehicle.');
    const validate = recordValidators.get(record.kind);
    requireValue(Boolean(validate), 'This record kind is not supported. Your stored data has not been changed.');
    validate(record, collection);
  }
  for (const marker of collection.tombstones) {
    shape(marker, ['id', 'kind', 'deletedAt'], 'Deletion marker');
    unique(marker.id);
    requireValue(marker.kind === 'vehicle', 'Unsupported deletion kind.');
    timestamp(marker.deletedAt);
  }
  return collection;
}

export function createCollection() {
  return { format: FORMAT, schemaVersion: SCHEMA_VERSION, id: crypto.randomUUID(), vehicles: [], records: [], tombstones: [] };
}

export function getVehicle(collection, vehicleId) {
  validateCollection(collection);
  const vehicle = collection.vehicles.find(value => value.id === vehicleId);
  requireValue(Boolean(vehicle), 'Select an existing vehicle.');
  return structuredClone(vehicle);
}

export function saveVehicle(collection, details, vehicleId = null) {
  validateCollection(collection);
  details = { make: '', model: '', year: null, notes: '', ...details };
  shape(details, ['name', 'odometerUnit', 'make', 'model', 'year', 'notes'], 'Vehicle details');
  vehicleDetails(details);
  const next = structuredClone(collection);
  const now = new Date().toISOString();
  const previous = vehicleId === null ? null : getVehicle(collection, vehicleId);
  const vehicle = {
    id: previous?.id ?? crypto.randomUUID(),
    ...details,
    name: details.name.trim(),
    createdAt: previous?.createdAt ?? now,
    updatedAt: now,
  };
  if (previous) next.vehicles[next.vehicles.findIndex(value => value.id === vehicle.id)] = vehicle;
  else next.vehicles.push(vehicle);
  validateCollection(next);
  return { collection: next, vehicleId: vehicle.id };
}

export function removeVehicle(collection, vehicleId) {
  getVehicle(collection, vehicleId);
  requireValue(!collection.records.some(record => record.vehicleId === vehicleId), 'Remove associated records before removing this vehicle.');
  const next = structuredClone(collection);
  next.vehicles = next.vehicles.filter(vehicle => vehicle.id !== vehicleId);
  next.tombstones.push({ id: vehicleId, kind: 'vehicle', deletedAt: new Date().toISOString() });
  return validateCollection(next);
}

assets.storage.js:
import { validateCollection } from './history.js';

export const DATABASE_NAME = 'car-maintenance-tracker';
const DATABASE_VERSION = 1;

export function serialize(collection) {
  return JSON.stringify(validateCollection(collection));
}

export function deserialize(json) {
  // Version one is the first persisted release. Future versions must migrate
  // here, explicitly and without dropping original IDs or factual observations.
  return validateCollection(JSON.parse(json));
}

function validateSnapshot(snapshot) {
  validateCollection(snapshot.collection);
  if (snapshot.selectedVehicleId !== null && !snapshot.collection.vehicles.some(vehicle => vehicle.id === snapshot.selectedVehicleId)) {
    throw new Error('The selected vehicle is missing from this collection.');
  }
}

export function createLocalStorage({ indexedDB = globalThis.indexedDB, databaseName = DATABASE_NAME } = {}) {
  let connection;
  function open() {
    if (connection) return connection;
    connection = new Promise((resolve, reject) => {
      if (!indexedDB) { reject(new Error('This browser does not provide local storage.')); return; }
      const request = indexedDB.open(databaseName, DATABASE_VERSION);
      let blocked = false;
      request.onupgradeneeded = () => {
        const db = request.result;
        if (!db.objectStoreNames.contains('workspace')) db.createObjectStore('workspace');
      };
      request.onblocked = () => {
        blocked = true;
        reject(new Error('Close other Car Maintenance Tracker tabs, then retry.'));
      };
      request.onerror = () => reject(request.error);
      request.onsuccess = () => {
        const db = request.result;
        if (blocked) { db.close(); return; }
        db.onversionchange = () => { db.close(); connection = undefined; };
        resolve(db);
      };
    }).catch(error => { connection = undefined; throw error; });
    return connection;
  }

  async function load() {
    const db = await open();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction('workspace', 'readonly');
      const request = transaction.objectStore('workspace').get('active');
      transaction.onabort = () => reject(transaction.error ?? new Error('Local read was interrupted.'));
      transaction.oncomplete = () => {
        try {
          if (request.result === undefined) { resolve(null); return; }
          const saved = request.result;
          const snapshot = { collection: deserialize(saved.json), selectedVehicleId: saved.selectedVehicleId, revision: saved.revision };
          validateSnapshot(snapshot);
          if (!Number.isSafeInteger(snapshot.revision) || snapshot.revision < 1) throw new Error('Invalid local revision.');
          resolve(snapshot);
        } catch (error) { reject(error); }
      };
    });
  }

  async function save(snapshot) {
    validateSnapshot(snapshot);
    const json = serialize(snapshot.collection);
    const selectedVehicleId = snapshot.selectedVehicleId;
    const revision = snapshot.revision;
    if (!Number.isSafeInteger(revision) || revision < 0) throw new Error('Invalid local revision.');
    const db = await open();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction('workspace', 'readwrite');
      const store = transaction.objectStore('workspace');
      const read = store.get('active');
      let failure;
      read.onsuccess = () => {
        if ((read.result?.revision ?? 0) !== revision) {
          failure = new Error('Another tab changed this collection. Keep your edits here; reopen in another tab to compare before reloading.');
          transaction.abort();
          return;
        }
        store.put({ json, selectedVehicleId, revision: revision + 1 }, 'active');
      };
      transaction.onabort = () => reject(failure ?? transaction.error ?? new Error('Local save was interrupted.'));
      // A successful request is not a committed transaction.
      transaction.oncomplete = () => resolve({ revision: revision + 1 });
    });
  }

  return { load, save };
}

